async def act(page):
    """
    Navigate to the Customer Reviews admin page and extract the total number of reviews.

    Strategy:
    - Use a relative goto to the known reviews URL (/index.php/admin/review_customer/).
    - Wait for the page to settle.
    - Read accessible text using accessibility-role-focused selectors (page.get_by_role).
    - Inspect the document region first, then any tables on the page, for common Magento pager text
      like "Displaying 1 - 20 of 42" or "of 42 records". Also detect explicit "No records found"
      markers which imply a total of 0.
    - Print the numeric total if discovered, otherwise print 'UNKNOWN'.

    Notes: This implementation avoids CSS locators and follows the accessibility-centric
    selector guidance (page.get_by_role()).
    """
    import re

    # Navigate directly to the Customer Reviews admin page (relative path)
    await page.goto('/index.php/admin/review_customer/')
    # Wait for network idle where possible and a short pause to allow widgets/grids to render
    try:
        await page.wait_for_load_state('networkidle')
    except Exception:
        pass
    await page.wait_for_timeout(800)

    # Helper to search for total in a text block
    def find_total_in_text(text: str):
        if not text:
            return None
        txt = text.replace('\u00a0', ' ')
        # Common Magento pager patterns
        patterns = [
            r'Displaying\s+\d+\s*-\s*\d+\s*of\s*([0-9,]+)',
            r'Displaying\s+\d+\s+to\s+\d+\s+of\s+([0-9,]+)',
            r'Records\s+\d+\s*-\s*\d+\s+of\s+([0-9,]+)',
            r'of\s+([0-9,]+)\s+records?',
            r'([0-9]{1,3}(?:,[0-9]{3})+)\s+records?',
            r'of\s+([0-9,]+)',
        ]
        for pat in patterns:
            m = re.search(pat, txt, re.IGNORECASE)
            if m:
                try:
                    return int(m.group(1).replace(',', ''))
                except Exception:
                    continue
        # Explicit "No records" -> zero
        if re.search(r'no\s+records\s+found|no\s+data\s+found', txt, re.IGNORECASE):
            return 0
        return None

    total = None

    # 1) Try the document region (preferred)
    doc_locator = page.get_by_role('document')
    if await doc_locator.count() > 0:
        try:
            doc_text = await doc_locator.nth(0).inner_text()
            total = find_total_in_text(doc_text)
        except Exception:
            total = None

    # 2) If not found, scan tables (grids often render as tables)
    if total is None:
        table_locator = page.get_by_role('table')
        tbl_count = 0
        try:
            tbl_count = await table_locator.count()
        except Exception:
            tbl_count = 0
        for i in range(tbl_count):
            try:
                ttext = await table_locator.nth(i).inner_text()
            except Exception:
                continue
            total = find_total_in_text(ttext)
            if total is not None:
                break

    # 3) As a last resort, try region/group/status roles for pager-like text
    if total is None:
        for role_name in ('region', 'group', 'status'):
            loc = page.get_by_role(role_name)
            try:
                c = await loc.count()
            except Exception:
                c = 0
            for i in range(c):
                try:
                    t = await loc.nth(i).inner_text()
                except Exception:
                    continue
                total = find_total_in_text(t)
                if total is not None:
                    break
            if total is not None:
                break

    # Print the discovered total or UNKNOWN so the runner can capture stdout
    if total is None:
        print('UNKNOWN')
    else:
        print(total)

